(6, '/fisica'),
(7, '/filosofia'),
(8, '/historia'),
(9, '/ingles'),
(10, '/quimica'),
(11, '/sociologia');

SELECT
    d.id_disciplina,
    d.nome,
    dp.rota
FROM disciplinas d
INNER JOIN disciplinas_paginas dp
    ON d.id_disciplina = dp.id_disciplina
ORDER BY d.id_disciplina;

